import "core-js/modules/es.array.push.js";
export default {
  props: {
    locationlogged: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      center: {
        lat: 45.508,
        lng: -73.587
      },
      markers: [],
      places: [],
      currentPlace: null
    };
  },
  watch: {
    locationlogged: {
      async handler() {
        if (this.locationlogged == true) {
          if (this.rowInfo.lat != null && this.rowInfo.long != null) {
            this.markers = [];
            var marker = {
              lat: Number(this.rowInfo.lat),
              lng: Number(this.rowInfo.long)
            };
            this.markers.push({
              position: marker
            });
          }
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    callposition(latLng) {
      this.markers = [];
      var marker = {
        lat: latLng.latLng.lat(),
        lng: latLng.latLng.lng()
      };
      this.markers.push({
        position: marker
      });
    }
  }
};
